    Sparse mass(n,n),stiffness(n,n);mass.setFromTriplets(massEntries.begin(),massEntries.end());stiffness.setFromTriplets(stiffnessEntries.begin(),stiffnessEntries.end());for(const auto* matrix:{&mass,&stiffness})for(int col=0;col<matrix->outerSize();++col)for(Sparse::InnerIterator entry(*matrix,col);entry;++entry)if(!std::isfinite(entry.value()))throw Failure(PENTA_NUMERIC_DOMAIN,"Surface assembly overflowed.");const Eigen::VectorXd weights=mass*Eigen::VectorXd::Ones(n);const double totalArea=weights.sum();if(!std::isfinite(totalArea)||totalArea<=0)throw Failure(PENTA_NUMERIC_DOMAIN,"Surface mass is not positive and finite.");
