    auto save=[&](double time,const Dense& values){if(samples>=result->capacity)throw Failure(7,"Surface output capacity exhausted.");result->times[samples]=time;long double energy=0;for(unsigned c=0;c<r.width;++c){long double integral=0;for(uint64_t node=0;node<n;++node){work.spend();const auto value=values(node,c);if(!std::isfinite(value))throw Failure(PENTA_NUMERIC_DOMAIN,"Surface solution is not finite.");result->values[(samples*n+node)*r.width+c]=value;integral+=static_cast<long double>(weights[node])*value;}const auto massValue=finite(integral);if(!samples)initialMass[c]=massValue;maxDrift[c]=std::max(maxDrift[c],std::abs(massValue-initialMass[c]));result->means[samples*r.width+c]=finite(integral/totalArea);const Eigen::VectorXd product=mass*values.col(c);for(uint64_t node=0;node<n;++node)energy+=static_cast<long double>(values(node,c))*product[node];}result->energy[samples]=finite(energy/2);if(samples)maxEnergyIncrease=std::max(maxEnergyIncrease,result->energy[samples]-previousEnergy);previousEnergy=result->energy[samples];++samples;};save(r.t0,state);
